package reconstruct

import (
	"context"
	"testing"

	"github.com/bnb-chain/tss-lib/v2/ecdsa/keygen"
	"github.com/stretchr/testify/assert"

	"github.com/nsuiteio/nst-mpc-key-export/utility/keyutil"
	"github.com/nsuiteio/nst-mpc-key-export/utility/strutil"
)

func TestReconstructECDSA(t *testing.T) {
	ctx := context.Background()

	testCases := []struct {
		threshold   int
		localShares []string
		expected    string
	}{
		{
			threshold: 2,
			localShares: []string{
				"",
				"",
				"",
			},
			expected: "0x39d027048a643fbac5f4a903a33e4a70d6bc69684e602973ac9e054cf8d56435",
		},
		{
			threshold: 3,
			localShares: []string{
				"",
				"",
				"",
			},
			expected: "0x9a474709c4b905434438ff9e5891234e0c028d80d376cf259fa7a1280cb43300",
		},
	}

	for _, tc := range testCases {
		t.Run(
			"", func(t *testing.T) {
				shares := make(
					[]*keygen.LocalPartySaveData,
					len(tc.localShares),
				)
				for i, shareHex := range tc.localShares {
					shareBs, err := strutil.FromHex(shareHex)
					if err != nil {
						t.Fatal(err)
					}
					share, err := keyutil.LocalDataFromBytesECDSA(ctx, shareBs)
					if err != nil {
						t.Fatal(err)
					}
					shares[i] = share
				}
				prvKey, err := ReconstructECDSA(ctx, tc.threshold, shares)
				if err != nil {
					t.Fatal(err)
				}
				prvStr := strutil.ToHex(prvKey.Serialize())
				assert.Equal(t, tc.expected, prvStr)
			},
		)
	}
}
